import { describe, expect, it, vi } from "vitest";
import {
	persistOpenAiViewSnapshot,
	readOpenAiCompatSnapshot,
	snapshotCapabilityFromOpenAiGlobals,
} from "./openai-compat";

describe("ChatGPT MCP app compatibility globals", () => {
	it("reads the result snapshot capability from compatibility metadata", () => {
		expect(
			snapshotCapabilityFromOpenAiGlobals({
				toolOutput: {},
				toolResponseMetadata: {
					mcp_tool_result: {
						_meta: {
							"lobu/mcp-app-snapshot-capability": "  restore-token  ",
						},
					},
				},
			}),
		).toBe("restore-token");
		expect(
			snapshotCapabilityFromOpenAiGlobals({
				toolOutput: { structuredContent: {} },
			}),
		).toBeUndefined();
		expect(
			snapshotCapabilityFromOpenAiGlobals({
				toolOutput: { structuredContent: {}, _meta: {} },
			}),
		).toBeNull();
	});

	it("restores structured content and the hidden approval capability", () => {
		expect(
			readOpenAiCompatSnapshot({
				toolOutput: { title: "Reloaded result", blocks: [] },
				toolResponseMetadata: {
					mcp_tool_result: {
						_meta: { "lobu/approval-capability": "signed-capability" },
					},
				},
			}),
		).toEqual({
			data: { title: "Reloaded result", blocks: [] },
			approvalCapability: "signed-capability",
		});
	});

	it("accepts the alternate full-result envelope ChatGPT exposes", () => {
		expect(
			readOpenAiCompatSnapshot({
				toolOutput: { rows: [{ row_number: 1 }] },
				toolResponseMetadata: {
					call_tool_result: {
						_meta: { "lobu/approval-capability": "alternate-capability" },
					},
				},
			}),
		).toEqual({
			data: { rows: [{ row_number: 1 }] },
			approvalCapability: "alternate-capability",
		});
	});

	it("unwraps structured content from a restored full tool result", () => {
		expect(
			readOpenAiCompatSnapshot({
				toolOutput: {
					structuredContent: { rows: [{ row_number: 1 }] },
					content: [{ type: "text", text: "1 row" }],
				},
			}),
		).toEqual({
			data: { rows: [{ row_number: 1 }] },
			approvalCapability: null,
		});
	});

	it("removes approval controls from a full result with no capability", () => {
		expect(
			readOpenAiCompatSnapshot({
				toolOutput: {
					structuredContent: {
						version: 1,
						actions: [
							{ id: "approve", tool: "resolve_lobu_approval" },
							{ id: "review", href: "https://lobu.ai/runs/42" },
						],
					},
				},
			}),
		).toEqual({
			data: {
				version: 1,
				actions: [{ id: "review", href: "https://lobu.ai/runs/42" }],
			},
			approvalCapability: null,
		});
	});

	it("retains full-result approval controls only with an embedded capability", () => {
		expect(
			readOpenAiCompatSnapshot({
				toolOutput: {
					structuredContent: {
						version: 1,
						actions: [{ id: "approve", tool: "resolve_lobu_approval" }],
					},
					_meta: { "lobu/approval-capability": "embedded-capability" },
				},
			}),
		).toEqual({
			data: {
				version: 1,
				actions: [{ id: "approve", tool: "resolve_lobu_approval" }],
			},
			approvalCapability: "embedded-capability",
		});
	});

	it("restores a versioned per-widget view snapshot when output is omitted", () => {
		expect(
			readOpenAiCompatSnapshot({
				widgetState: {
					privateContent: {
						lobuViewSnapshot: {
							version: 1,
							data: { title: "Cached view" },
						},
					},
				},
			}),
		).toEqual({
			data: { title: "Cached view" },
			approvalCapability: undefined,
		});
	});

	it("lets an explicit output clear override a cached snapshot", () => {
		expect(
			readOpenAiCompatSnapshot({
				toolOutput: null,
				widgetState: {
					privateContent: {
						lobuViewSnapshot: {
							version: 1,
							data: { title: "Stale view" },
						},
					},
				},
			}),
		).toEqual({ data: null, approvalCapability: undefined });
	});

	it("persists only display data while preserving unrelated widget state", () => {
		const setWidgetState = vi.fn();
		const globals = {
			widgetState: {
				publicContent: { page: 2 },
				privateContent: { anotherAppKey: "preserved" },
			},
			setWidgetState,
			toolResponseMetadata: {
				mcp_tool_result: {
					_meta: { "lobu/approval-capability": "must-not-persist" },
				},
			},
		};

		expect(
			persistOpenAiViewSnapshot(globals, { title: "Persisted view" }),
		).toBe(true);
		expect(setWidgetState).toHaveBeenCalledWith({
			publicContent: { page: 2 },
			privateContent: {
				anotherAppKey: "preserved",
				lobuViewSnapshot: {
					version: 1,
					data: { title: "Persisted view" },
				},
			},
		});
		expect(JSON.stringify(setWidgetState.mock.calls)).not.toContain(
			"must-not-persist",
		);
	});

	it("does not cache capability-gated approval controls", () => {
		const setWidgetState = vi.fn();
		expect(
			persistOpenAiViewSnapshot(
				{ setWidgetState },
				{
					version: 1,
					actions: [
						{
							id: "approve",
							tool: "resolve_lobu_approval",
							args: { run_id: 42, decision: "approve" },
						},
						{ id: "review", href: "https://lobu.ai/runs/42" },
					],
				},
			),
		).toBe(true);
		expect(setWidgetState).toHaveBeenCalledWith({
			privateContent: {
				lobuViewSnapshot: {
					version: 1,
					data: {
						version: 1,
						actions: [{ id: "review", href: "https://lobu.ai/runs/42" }],
					},
				},
			},
		});
	});

	it("does not restore approval controls after explicit metadata loss", () => {
		expect(
			readOpenAiCompatSnapshot({
				toolOutput: {
					version: 1,
					actions: [
						{ id: "approve", tool: "resolve_lobu_approval" },
						{ id: "review", href: "https://lobu.ai/runs/42" },
					],
				},
				toolResponseMetadata: null,
			}),
		).toEqual({
			data: {
				version: 1,
				actions: [{ id: "review", href: "https://lobu.ai/runs/42" }],
			},
			approvalCapability: null,
		});
	});

	it("rejects malformed output and unbounded capability values", () => {
		expect(
			readOpenAiCompatSnapshot({
				toolOutput: ["not", "a", "view"],
				toolResponseMetadata: {
					mcp_tool_result: {
						_meta: { "lobu/approval-capability": "x".repeat(4_097) },
					},
				},
			}),
		).toEqual({ data: null, approvalCapability: null });
	});

